from rest_framework.throttling import SimpleRateThrottle
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import WebhookSubscription

class WebhookDispatchRateThrottle(SimpleRateThrottle):
    scope = 'webhook_trigger'

    def get_cache_key(self, request, view):
        # Throttle by authenticated user and target webhook to prevent DoS on foreign webhooks
        webhook_id = view.kwargs.get('webhook_id')
        if not webhook_id or not request.user or not request.user.is_authenticated:
            return None
        return f"throttle_{self.scope}_{request.user.id}_{webhook_id}"

class TriggerWebhookTestView(APIView):
    permission_classes = [permissions.IsAuthenticated]
    throttle_classes = [WebhookDispatchRateThrottle]

    def post(self, request, webhook_id):
        # Scope webhook lookup to the authenticated user's organization
        hook = WebhookSubscription.objects.filter(id=webhook_id, organization=request.user.organization).first()
        if not hook:
            return Response({"error": "Webhook not found"}, status=status.HTTP_404_NOT_FOUND)
        return Response({"status": "Test payload dispatched", "webhook": hook.target_url})
